import{_ as n,c as s,o as a,ag as o}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Options de confidentialité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/privacy-choices.md","filePath":"fr/guide/privacy-choices.md","lastUpdated":1794112334000}'),t={name:"fr/guide/privacy-choices.md"};function i(r,e,d,l,u,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="options-de-confidentialite" tabindex="-1">Options de confidentialité <a class="header-anchor" href="#options-de-confidentialite" aria-label="Permalink to &quot;Options de confidentialité&quot;">​</a></h1><p>Cette page décrit comment soumettre des demandes de confidentialité à Nicasa et ce que vous pouvez attendre en retour.</p><h2 id="a-quoi-cela-sert" tabindex="-1">À quoi cela sert <a class="header-anchor" href="#a-quoi-cela-sert" aria-label="Permalink to &quot;À quoi cela sert&quot;">​</a></h2><p>Utilisez cette page pour demander l&#39;accès à des données personnelles, leur suppression, leur portabilité, ou pour vous opposer à certaines utilisations de données (par exemple, les demandes « Ne pas vendre » lorsque cela s&#39;applique).</p><p>Remarque : Nicasa ne collecte ni ne stocke actuellement de données personnelles (voir la Politique de confidentialité). Si vous pensez que nous détenons des données personnelles vous concernant, soumettez une demande et nous enquêterons.</p><h2 id="comment-soumettre-une-demande" tabindex="-1">Comment soumettre une demande <a class="header-anchor" href="#comment-soumettre-une-demande" aria-label="Permalink to &quot;Comment soumettre une demande&quot;">​</a></h2><p>Fournissez les informations suivantes lors d&#39;une demande pour nous aider à la traiter efficacement :</p><ul><li>Votre nom</li><li>E-mail de contact</li><li>Description de la demande (accès, suppression, portabilité ou opposition)</li><li>Tout identifiant aidant à localiser les enregistrements (par exemple, un identifiant de ticket d&#39;assistance)</li></ul><p>Envoyez les demandes à l&#39;un des canaux suivants :</p><ul><li>E-mail : <a href="mailto:nicasa@w3cub.com" target="_blank" rel="noreferrer">nicasa@w3cub.com</a></li><li>Ouvrir un ticket de confidentialité : <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a></li></ul><h2 id="delai-de-reponse" tabindex="-1">Délai de réponse <a class="header-anchor" href="#delai-de-reponse" aria-label="Permalink to &quot;Délai de réponse&quot;">​</a></h2><p>Nous nous efforçons d&#39;accuser réception et de répondre aux demandes valides dans un délai de 30 jours. Si nous avons besoin de plus de temps, nous vous informerons d&#39;un délai estimé.</p><h2 id="si-nous-ne-detenons-pas-de-donnees-personnelles" tabindex="-1">Si nous ne détenons pas de données personnelles <a class="header-anchor" href="#si-nous-ne-detenons-pas-de-donnees-personnelles" aria-label="Permalink to &quot;Si nous ne détenons pas de données personnelles&quot;">​</a></h2><p>Étant donné que Nicasa est conçu pour traiter les images localement et ne pas collecter de données utilisateur, de nombreuses demandes seront closes par une confirmation qu&#39;aucune donnée personnelle n&#39;est détenue. Si vous fournissez des preuves que des données personnelles ont été collectées, nous enquêterons et prendrons les mesures appropriées.</p><h2 id="ne-pas-vendre-opposition" tabindex="-1">Ne pas vendre / Opposition <a class="header-anchor" href="#ne-pas-vendre-opposition" aria-label="Permalink to &quot;Ne pas vendre / Opposition&quot;">​</a></h2><p>Si vous exercez un droit propre à votre juridiction (par exemple au titre du CCPA/CPRA) pour vous opposer à la vente, et que vous pensez que nous avons vendu vos données personnelles, décrivez les circonstances dans votre demande. Si nous ne vendons pas de données personnelles, nous le confirmerons dans notre réponse.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Si vous avez des questions sur ce processus, écrivez à <a href="mailto:nicasa@w3cub.com" target="_blank" rel="noreferrer">nicasa@w3cub.com</a> ou ouvrez un ticket sur <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a>.</p>',18)])])}const h=n(t,[["render",i]]);export{m as __pageData,h as default};
